									if (event.current.hasDisabledSlot('equip1')) types.remove(1);
									if (event.current.hasDisabledSlot('equip2')) types.remove(2);
									if (event.current.hasDisabledSlot('equip3')) types.remove(3);
									if (event.current.hasDisabledSlot('equip4')) types.remove(4);
									if (event.current.hasDisabledSlot('equip5')) types.remove(5);
