									lib.card[name] = get.copy(get.info(card));
									lib.card[name].subtype = 'equip' + i;
									lib.card[name].cardimage = card.name;
									lib.card[name].source_name = card.name;
									lib.translate[name] = lib.translate[card.name];
									lib.translate[name + '_info'] = lib.translate[card.name + '_info'];
